            if (messages.length === 0) {
                if (cursor === 0 && State.coverTag) {
                    if (State.preparedTag) {
                        const prep = State.gallery.get(State.preparedTag);
                        if (prep) { setCurrent(prep.tag, 'replay', true); State.playback.cursor = 1; }
                    }
                    return;
                }
                return;
            }
            if (cursor === -1) return;
            if (cursor === 0 && State.coverTag) {
